"""Paired run25 contracts; no accepted output is regenerated by this suite."""
import copy
import math
import sys
import unittest
from pathlib import Path

sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from run25 import model, engine, paired
from hybridcalc.inputs import InputGap
from hybridcalc.session_hosting import route


class Run25Contracts(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.context,cls.prepared,cls.coverage = engine.setup()
        cls.meta,cls.econ,cls.weights = cls.prepared[0]
        cls.cfg = model.config()
        cls.case = cls.cfg['storage_cases'][1]
        cls.fleet = model.Fleet(cls.econ,cls.weights,cls.case,1,'bought')

    # Complete-copy storage must bind; GPU residency is not a hidden extra tier.
    def test_too_small_storage_refuses_with_expanded_positive_control(self):
        inherited = model.Fleet(self.econ,self.weights,self.cfg['storage_cases'][0],1,'bought')
        row = inherited.evaluate(50,40,1)
        self.assertEqual(row['status'],'storage_shortfall')
        self.assertEqual(row['storage_shortfall_copies'],146)
        self.assertEqual(row['person_month'],'')
        self.assertFalse(row['feasible'])
        self.assertEqual(self.fleet.evaluate(50,40,1)['status'],'feasible')

    # A failed mean-delay admission never masquerades as a finite cheap fleet.
    def test_too_small_latency_bound_refuses_with_positive_control(self):
        cfg = copy.deepcopy(self.cfg); cfg['max_mean_queue_s'] = 0
        _,econ,weights=self.prepared[2]
        normal=model.Fleet(econ,weights,self.case,1,'bought')
        demand=normal.trial(50,1,4,0)['client_capacity_day']+.0001
        f = model.Fleet(econ,weights,self.case,1,'bought',cfg)
        row = f.evaluate(50,demand,4)
        self.assertEqual(row['status'],'latency_or_compute_shortfall')
        self.assertEqual(row['person_month'],'')
        self.assertFalse(row['feasible'])
        self.assertEqual(normal.evaluate(50,demand,4)['status'],'feasible')

    # A rejected remote queue can fall back locally, but excess generation
    # remains charged to the server rather than silently discarded.
    def test_queue_refusal_uses_local_capacity_without_dropping_overflow(self):
        profitable=self.fleet.evaluate(50,40,1)
        self.assertGreater(profitable['offload_share'],0)
        self.assertEqual(profitable['prefill_route'],'profitable_offload')
        row=self.fleet.evaluate(50,500,1)
        self.assertEqual(row['status'],'feasible')
        self.assertEqual(row['prefill_route'],'local_after_remote_queue_refusal')
        self.assertEqual(row['offload_share'],0)
        self.assertEqual(row['server_decode_overflow_day'],0)
        self.assertEqual(row['actual_mean_queue_s'],0)
        capacity=self.fleet.trial(50,1,1,0,True)['client_capacity_day']
        overflow=self.fleet.trial(50,capacity+1,1,0,True)
        self.assertGreater(overflow['server_decode_overflow_day'],0)
        self.assertGreater(overflow['pending_s_overflow'],0)
        self.assertLessEqual(overflow['pending_s_overflow'],self.fleet.cold_journal_bound)
        self.assertGreater(overflow['mean_server_decode_overflow_ttft_s'],0)
        refused=self.fleet.evaluate(50,1000000,1)
        self.assertEqual(refused['status'],'latency_or_compute_shortfall')
        self.assertEqual(refused['person_month'],'')

    # Analytic collision delay is nonzero and an unstable queue is not free.
    def test_unstable_queue_cannot_report_zero_delay_with_analytic_control(self):
        rho,delay = model.mg1(.1,2,4,1)
        self.assertAlmostEqual(rho,.2); self.assertAlmostEqual(delay,.25)
        self.assertTrue(math.isinf(model.mg1(1,2,4,1)[1]))
        self.assertLess(model.mg1(.1,2,4,2)[1],delay)
        with self.assertRaisesRegex(InputGap,'invalid queue moments'):
            model.mg1(.1,2,1,1)

    # Restore AND writeback occupy the declared sequential node; slower is real.
    def test_checkpoint_writeback_cannot_disappear_with_twofold_control(self):
        f = self.fleet; slow = model.Fleet(self.econ,self.weights,self.case,2,'bought')
        i = 0
        expected = f.read[i]+f.p.pre[i]+f.save[i]+f.p.wire[i]/f.link['bytes_s']
        self.assertAlmostEqual(f.base_service[i],expected)
        self.assertGreater(f.save[i],0)
        self.assertEqual(slow.read[i],2*f.read[i])
        self.assertEqual(slow.save[i],2*f.save[i])

    # The fast prefix policy matches the existing greatest-stable Bernoulli rule.
    def test_pending_catchup_cannot_be_omitted_with_native_route_control(self):
        f = self.fleet
        for queue in (0,.5,2):
            native = route(f.p.own,[x+queue for x in f.remote],f.p.shadow,f.p.output,f.p.wire,f.p.imports,'at_offload')
            k,pending = f.route(queue)
            self.assertEqual(k,sum(x[3] for x in native))
            self.assertAlmostEqual(pending,native.pending_seconds,places=10)
        self.assertGreater(f.route(0)[1],0)

    # Reweighting matches two token marginals without inventing raw observations.
    def test_reweighting_cannot_claim_observed_coverage_with_moment_control(self):
        for meta,econ,weights in self.prepared:
            self.assertAlmostEqual(sum(weights),1)
            self.assertTrue(all(w>0 for w in weights))
            self.assertIn('not observed',meta['coverage_basis'])
            if meta['weighting']=='full_delta_output_mix':
                row = next(r for r in self.coverage if r['profile']==meta['profile'])
                self.assertAlmostEqual(sum(w*x[1] for w,x in zip(weights,econ.calls)),row['full_mean_new'],places=5)
                self.assertAlmostEqual(sum(w*x[2] for w,x in zip(weights,econ.calls)),row['full_mean_output'],places=5)
                self.assertEqual(row['observed_log_work_share'],'')
        with self.assertRaisesRegex(InputGap,'cannot be matched'):
            model.reweight([(1,1,1,0),(2,2,2,0)],[100,100])

    # Fixed fleets that later overflow storage have intervals, not an invented
    # sustained crossing through500. A fully feasible winner remains admissible.
    def test_storage_refusal_cannot_be_skipped_in_crossing_with_control(self):
        row = engine.compare([3,2,None],[4,4,4])
        self.assertEqual(row['sustained_from'],'')
        self.assertEqual(row['cheaper_team_intervals'],'[[1,2]]')
        self.assertEqual(engine.compare([3,2,1],[4,4,4])['sustained_from'],1)

    # The server full checkpoint and client bf16 wire must not be conflated.
    def test_bf16_transport_cannot_halve_server_slot_with_control(self):
        sv = self.econ.servers['pro6000_fp8']
        self.assertEqual(sv.session_bytes(249000),16475357184)
        self.assertEqual(model.storage(sv,249000,50,4,self.case)['retained_copies'],200)
        self.assertNotEqual(sv.session_bytes(249000),249000*34816+78446592)

    # The new office proxy cannot silently be used as an all-in rental price.
    def test_unscoped_rental_cannot_receive_office_cost_with_control(self):
        with self.assertRaisesRegex(InputGap,'bought-office only'):
            model.Fleet(self.econ,self.weights,self.case,1,'rented')
        self.assertEqual(self.fleet.evaluate(50,40,1)['status'],'feasible')

    # Uniform weighting preserves the native own-cluster fleet and cost.
    def test_weighted_own_cannot_change_uniform_baseline_with_control(self):
        from run23 import economics as e
        native = e.Economics(self.context,self.econ.calls,self.econ.servers,self.econ.cfg)
        for team in (3,50):
            a = native.own('pro6000_fp8',team,40)
            b = self.econ.own('pro6000_fp8',team,40)
            self.assertEqual(a['boxes'],b['boxes'])
            self.assertEqual(a['person_month'],b['person_month'])

    # Symmetric retention rejects storage and excessive service/queue demand;
    # a minimum search supplies a finite all-server positive control.
    def test_paired_own_cannot_hide_storage_shortfall_with_control(self):
        inherited = model.Fleet(self.econ,self.weights,self.cfg['storage_cases'][0],1,'bought')
        row = paired.own_at(inherited,50,40,1)
        self.assertEqual(row['status'],'storage_shortfall')
        self.assertEqual(row['person_month'],'')
        good = paired.own_minimum(self.fleet,50,40)
        self.assertEqual(good['status'],'feasible')
        self.assertGreater(good['person_month'],0)
        overloaded=paired.own_at(self.fleet,50,1000000,4)
        self.assertEqual(overloaded['status'],'latency_or_compute_shortfall')
        self.assertEqual(overloaded['person_month'],'')


if __name__=='__main__':
    unittest.main()
